import raw from './site.json'
import type { XZ } from '../lib/geo'

/** Typed view of site.json (generated by scripts/build-site.mjs from OpenStreetMap). */
export interface SiteData {
  source: string
  origin: { lat: number; lon: number }
  ktiz: { id: number; pts: XZ[] }
  buildings: { id: number; name: string | null; h: number; pts: XZ[] }[]
  roads: { id: number; kind: string; name: string | null; w: number; pts: XZ[] }[]
  water: { id: number; pts: XZ[] }[]
  green: { id: number; pts: XZ[] }[]
}

export const site = raw as unknown as SiteData
